import { BaseException } from '../../base-exception';
import { Locale } from '../../locale';

export class InactiveSessionException extends BaseException {
    constructor() {
        super(
            'Game.InactiveSession',
            'User has been idle'
        );
    }

    public localise(locale: Locale) {
        this.buttonText = this.getButtonText(locale);

        switch (locale) {
            case 'it-it':
                this.displayMessage = 'Sei stato inattivo per troppo tempo, per favore chiudi il gioco e riaprilo per continuare a giocare';
                break;
            case 'es-es':
                this.displayMessage = '¡Vaya! Estuviste fuera un rato. Por favor, inicia sesión otra vez.';
                break;
            default:
                this.displayMessage = 'Oops! You\'ve been away from the screen too long. Please log back in.';
                break;
        }
    }
}
